 			&viommu->pgsize_bitmap);
@@ -1236,7 +1237,9 @@ static int viommu_probe(struct virtio_device *vdev)

 	vdev->priv = viommu;

-	iommu_device_register(&viommu->iommu, &viommu_ops, parent_dev);
